import type { ColorValue } from "react-native";
import Svg, { Circle, Path, type SvgProps } from "react-native-svg";

import { colors } from "@/theme/colors";

/**
 * Icon set for the app UI.
 *
 * Vector data is exported verbatim from the Figma "TeamNap" file
 * (Phosphor-style icons used across the S02 screens), mirroring the
 * approach already used by `Logo.tsx`. Every icon scales from its own
 * intrinsic viewBox and takes a `size` (px) and `color`.
 */

export type IconProps = Omit<SvgProps, "width" | "height" | "color"> & {
  /** Rendered width & height in px. */
  size?: number;
  /** Fill color. Defaults to the design's default icon color. */
  color?: ColorValue;
};

const DEFAULT_COLOR = "#44585A"; // --tn-icon-default

function Icon24({
  size = 24,
  color = DEFAULT_COLOR,
  d,
  ...rest
}: IconProps & { d: string }) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none" {...rest}>
      <Path d={d} fill={color} />
    </Svg>
  );
}

